324 +  }
325 +
326 +  return <CardBody>{link}</CardBody>;
327 +};
328 +
329 +const onStatusLinks: OnElementHandler<AccountStatusShape> = (
330 +  element,
331 +  { key, href },
332 +  children,
333 +  status,
334 +) => {
335 +  // If this is a paragraph with just a link and it matches the card, don't add it.
336 +  if (
337 +    element instanceof HTMLParagraphElement &&
338 +    element.children.length === 1 &&
339 +    element.firstChild instanceof HTMLAnchorElement &&
340 +    element.firstChild.href === status.card?.url
341 +  ) {
342 +    return null;
343 +  } else if (element instanceof HTMLAnchorElement) {
344 +    if (href === status.card?.url) {
345 +      return null;
346 +    }
347 +    return <strong key={key as string}>{children}</strong>;
348 +  }
349 +  return undefined;
350 +};
