352 +function useQuoteError({
353 +  quoted_status: quoteId,
354 +  state: quoteState,
355 +  parentId,
356 +}: StatusQuoteProps) {
357 +  const { state: loadingState, status: quote } = useAppSelector((state) =>
358 +    selectStatusLoadingState(state, { statusId: quoteId }),
359 +  );
360 +  const accountId = quote?.account.id;
361 +  const account = useAppSelector((state) =>
362 +    selectPlainAccount(state, accountId),
363 +  );
364 +  const quoteAuthorName = account?.acct;
365 +  const domain = quoteAuthorName?.split('@')[1];
366 +  const dispatch = useAppDispatch();
367 +  const onRevealAccount = useCallback(() => {
368 +    if (accountId) {
369 +      dispatch(revealAccount({ id: accountId }));
370 +    }
371 +  }, [dispatch, accountId]);
372 +
373 +  const hiddenAccount = useAppSelector(
374 +    (state) => accountId && selectAccountHidden(state, accountId),
375 +  );
376 +
377 +  let message: React.ReactNode = null;
378 +  let action: VoidFunction | null = null;
379 +  const [reference, setReference] = useState<HTMLButtonElement | null>(null);
380 +  const [revealed, { onTrue: onRevealQuote }] = useToggle();
381 +  const [showInfo, { onFalse: onHideInfo, onToggle: onInfoToggle }] =
382 +    useToggle();
383 +
384 +  const shouldFetchQuote =
385 +    !quote?.isLoading &&
386 +    quoteState !== 'deleted' &&
387 +    loadingState === 'not-found';
388 +  useEffect(() => {
389 +    if (shouldFetchQuote && quoteId) {
390 +      dispatch(
391 +        fetchStatus(quoteId, {
392 +          parentQuotePostId: parentId,
393 +          alsoFetchContext: false,
394 +        }),
395 +      );
396 +    }
397 +  }, [shouldFetchQuote, dispatch, quoteId, parentId]);
398 +
399 +  if (quoteState === 'pending') {
400 +    return (
401 +      <>
402 +        <FormattedMessage
403 +          id='status.quote_error.pending_approval'
404 +          defaultMessage='Post pending'
405 +        />
406 +
407 +        <Button
408 +          size='xs'
409 +          variant='ghost'
410 +          onClick={onInfoToggle}
411 +          ref={setReference}
412 +          aria-expanded={showInfo}
413 +          className={classes.errorButton}
414 +        >
415 +          <FormattedMessage
416 +            id='learn_more_link.learn_more'
417 +            defaultMessage='Learn more'
418 +          />
419 +        </Button>
420 +
421 +        <PopoverMenuCard
422 +          reference={reference}
423 +          onClose={onHideInfo}
424 +          isOpen={showInfo}
425 +          maxWidth={200}
426 +          className={classes.infoPopup}
427 +          placement='bottom-end'
428 +        >
429 +          <FormattedMessage
430 +            id='status.quote_error.pending_approval_popout.body'
431 +            defaultMessage="On Mastodon, you can control whether someone can quote you. This post is pending while we're getting the original author's approval."
432 +            tagName='p'
433 +          />
434 +        </PopoverMenuCard>
435 +      </>
436 +    );
437 +  }
438 +
439 +  if (loadingState === 'filtered') {
440 +    message = (
441 +      <FormattedMessage
442 +        id='status.quote_error.filtered'
443 +        defaultMessage='Hidden due to one of your filters'
444 +      />
445 +    );
446 +  } else if (quoteState === 'revoked') {
447 +    message = (
448 +      <FormattedMessage
449 +        id='status.quote_error.revoked'
450 +        defaultMessage='Post removed by author'
451 +      />
452 +    );
453 +  } else if (
454 +    (quoteState === 'blocked_account' ||
455 +      quoteState === 'blocked_domain' ||
456 +      quoteState === 'muted_account') &&
457 +    !revealed &&
458 +    accountId
459 +  ) {
460 +    action = onRevealQuote;
461 +
462 +    switch (quoteState) {
463 +      case 'blocked_account':
464 +        message = (
465 +          <FormattedMessage
466 +            id='status.quote_error.blocked_account_hint.title'
467 +            defaultMessage="This post is hidden because you've blocked @{name}."
468 +            values={{ name: quoteAuthorName }}
469 +          />
470 +        );
471 +        break;
472 +      case 'blocked_domain':
473 +        message = (
474 +          <FormattedMessage
475 +            id='status.quote_error.blocked_domain_hint.title'
476 +            defaultMessage="This post is hidden because you've blocked {domain}."
477 +            values={{ domain }}
478 +          />
479 +        );
480 +        break;
481 +      case 'muted_account':
482 +        message = (
483 +          <FormattedMessage
484 +            id='status.quote_error.muted_account_hint.title'
485 +            defaultMessage="This post is hidden because you've muted @{name}."
486 +            values={{ name: quoteAuthorName }}
487 +          />
488 +        );
489 +    }
490 +  } else if (
491 +    !quote?.id ||
492 +    quoteState === 'deleted' ||
493 +    quoteState === 'rejected' ||
494 +    quoteState === 'unauthorized'
495 +  ) {
496 +    message = (
497 +      <FormattedMessage
498 +        id='status.quote_error.not_available'
499 +        defaultMessage='Post unavailable'
500 +      />
501 +    );
502 +  } else if (hiddenAccount && accountId) {
503 +    action = onRevealAccount;
504 +    message = (
505 +      <FormattedMessage
506 +        id='status.quote_error.limited_account_hint.title'
507 +        defaultMessage='This account has been hidden by the moderators of {domain}.'
508 +        values={{ domain }}
509 +      />
510 +    );
511 +  }
512 +
513 +  if (!message) {
514 +    return null;
515 +  }
516 +
517 +  return (
518 +    <>
519 +      {message}
520 +
521 +      {action && (
522 +        <Button
523 +          size='xs'
524 +          variant='ghost'
525 +          onClick={action}
526 +          className={classes.errorButton}
527 +        >
528 +          <FormattedMessage
529 +            id='status.quote_error.limited_account_hint.action'
530 +            defaultMessage='Show anyway'
531 +          />
532 +        </Button>
533 +      )}
534 +    </>
535 +  );
536 +}

