@use '@/styles/mastodon/mixins';

.root {
  --col-gap: var(--space-xs);
  --avatar-size: 40px;
  --content-col: 2;

  display: grid;
  grid-template-columns: calc(var(--avatar-size) + var(--col-gap)) auto;
  grid-template-rows: minmax(calc(var(--avatar-size) + var(--col-gap)), auto);
  grid-auto-rows: auto;
  row-gap: var(--space-xs);
  padding: var(--space-md);
}

.variantThread {
  --avatar-size: 32px;

  padding: var(--space-xs) 0;
}

.variantPage {
  padding: 0;
}

.isQuote {
  padding: var(--space-sm);
}

.variantPage,
.isQuote {
  --content-col: span 2;
}

.header {
  grid-column: span 2;
}

.content,
.footer,
.root :global(.status__prepend),
.root :global(.content-warning) {
  grid-column: var(--content-col);
}

.content {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);

  &.collapsed {
    position: relative;
    max-height: 15lh;
    overflow-y: clip;

    &::after {
      content: '';
      position: absolute;
      inset-inline: 0;
      inset-block-end: 0;
      height: calc(var(--space-4xl) * 2);
      background: linear-gradient(
        to bottom,
        transparent,
        var(--color-bg-blend)
      );
      pointer-events: none;
    }
  }
}

.contentText {
  @include mixins.type-body;

  p:not(:last-child) {
    margin-block-end: 1em;
  }

  a {
    color: var(--color-text-brand);
  }
}

.contentImage {
  border-radius: var(--radius-md);
  position: relative;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  overflow: hidden;
}

.contentBlurHash {
  width: 100%;
  height: 100%;
}

.contentReadMore {
  position: absolute;
  inset-block-end: 0;
  inset-inline-start: 0;
  z-index: 1;
}

.meta {
  @include mixins.type-micro;

  color: var(--color-text-secondary);
}

.actions {
  display: flex;

  button:not(:hover, :active) {
    opacity: 0.7;
  }
}

.actionsButtonGap {
  margin-inline-end: auto;
}

.buttonAlign {
  margin-inline-start: calc(-1 * var(--space-sm));
}

