import type { ReactNode, SVGProps } from 'react';

import classNames from 'classnames';
import { NavLink } from 'react-router-dom';
import type { NavLinkProps } from 'react-router-dom';

import type { Icon } from '@phosphor-icons/react';

import { Badge } from '@/mastodon/components/badge';
import { useIsLinkActive } from '@/mastodon/hooks/useIsLinkActive';

import classes from './navigation_link.module.scss';

type NavigationLinkProps = {
  stacked?: boolean;
  iconComponent?: Icon | React.FC<SVGProps<SVGSVGElement>>;
  badgeCount?: number;
  withSpaceAfter?: boolean;
} & (
  | ({ as?: 'button' } & React.ComponentPropsWithRef<'button'>)
  | ({ as?: 'link' } & NavLinkProps)
);

export const NavigationLink: React.FC<NavigationLinkProps> = ({
  stacked = false,
  as = 'link',
  iconComponent: IconComp,
  badgeCount = 0,
  withSpaceAfter,
  children,
  ...otherProps
}) => {
  let Comp: React.ElementType = as;
  if (as === 'link') {
    Comp = NavLink;
  }

  const isActive = useIsLinkActive(
    'to' in otherProps ? otherProps.to : undefined,
  );

  return (
    <li
      className={classNames(
        classes.wrapper,
        withSpaceAfter && classes.wrapperWithSpace,
      )}
    >
      <Comp
        {...otherProps}
        type={as === 'button' ? 'button' : undefined}
        className={classNames(classes.link, stacked && classes.linkStacked)}
      >
        {IconComp && (
          <span className={classes.icon}>
            <IconComp
              size={stacked ? 24 : 20}
              weight={isActive ? 'fill' : undefined}
            />
          </span>
        )}
        <span className={classes.label}>{children}</span>
        {badgeCount > 0 && (
          <Badge
            variant='accent'
            label={badgeCount}
            className={classes.badge}
          />
        )}
      </Comp>
    </li>
  );
};

type MobileNavLink = NavLinkProps & {
  withDot?: boolean;
  children: ReactNode;
  iconComponent: Icon | React.FC<SVGProps<SVGSVGElement>>;
};

export const MobileNavLink: React.FC<MobileNavLink> = ({
  iconComponent: IconComp,
  withDot,
  children,
  ...otherProps
}) => {
  const isActive = useIsLinkActive(
    'to' in otherProps ? otherProps.to : undefined,
  );

  return (
    <li>
      <NavLink
        {...otherProps}
        className={classNames(classes.link, classes.linkMobile)}
      >
        <span
          className={classNames(classes.icon, withDot && classes.iconWithDot)}
        >
          <IconComp size={24} weight={isActive ? 'fill' : undefined} />
        </span>
        <span className='sr-only'>{children}</span>
      </NavLink>
    </li>
  );
};

export const MobileNavProfileButton: React.FC<
  { avatar?: ReactNode } & Pick<MobileNavLink, 'children' | 'withDot'>
> = ({ children, avatar, withDot, ...otherProps }) => {
  return (
    <li>
      <button
        type='button'
        {...otherProps}
        className={classNames(classes.link, classes.linkMobile)}
      >
        <span
          className={classNames(classes.icon, withDot && classes.iconWithDot)}
        >
          {avatar}
        </span>
        <span className='sr-only'>{children}</span>
      </button>
    </li>
  );
};

import type React from 'react';
import { useMemo } from 'react';

import { FormattedDate, FormattedMessage } from 'react-intl';

import { Link } from 'react-router-dom';

import type {
  AnyStatusShape,
  StatusVisibility,
} from '@/mastodon/models/status';

import { statusLink } from './utils';

export const StatusMeta: React.FC<
  {
    status: Pick<
      AnyStatusShape,
      'account' | 'application' | 'created_at' | 'id' | 'visibility'
    >;
  } & React.ComponentPropsWithRef<'span'>
> = ({ status, ...props }) => {
  const { created_at, application } = status;

  const createdAt = useMemo(() => {
    try {
      return new Date(created_at);
    } catch {
      return null;
    }
  }, [created_at]);
  const visibility = useMemo(
    () => statusVisibilityText(status.visibility),
    [status.visibility],
  );

  if (!createdAt) {
    return null;
  }

  const createdLink = (
    <Link to={statusLink(status)}>
      <FormattedDate
        value={createdAt}
        year='numeric'
        month='short'
        day='2-digit'
        hour='2-digit'
        minute='2-digit'
      />
    </Link>
  );

  let applicationLink: React.ReactNode = application?.name;
  if (application?.website) {
    applicationLink = (
      <a href={application.website} target='_blank' rel='noopener noreferrer'>
        {application.name}
      </a>
    );
  }

  return (
    <span {...props}>
      {applicationLink ? (
        <FormattedMessage
          id='status.meta'
          defaultMessage='{createdAt} on {source} {sep} {visibility}'
          values={{
            createdAt: createdLink,
            source: applicationLink,
            visibility,
            sep: <>&bull;</>,
          }}
        />
      ) : (
        <FormattedMessage
          id='status.meta.no_application'
          defaultMessage='{createdAt} {sep} {visibility}'
          values={{
            createdAt: createdLink,
            visibility,
            sep: <>&bull;</>,
          }}
        />
      )}
    </span>
  );
};

function statusVisibilityText(visibility: StatusVisibility) {
  switch (visibility) {
    case 'private':
      return (
        <FormattedMessage
          id='privacy.private.short'
          defaultMessage='Followers'
        />
      );
    case 'direct':
      return (
        <FormattedMessage
          id='privacy.message.short'
          defaultMessage='Message'
          description='Message refers to a direct message. For languages where this is confusing, "chat" or "direct message" can be used.'
        />
      );

    default:
      return (
        <FormattedMessage id='privacy.public.short' defaultMessage='Public' />
      );
  }
