  pre:not(.highlight),
  div:not(.highlight)>pre.highlight,
  div.highlight {
    margin: 0 0 var(--content-rhythm) 0;
  }

  // This .ff-container classname is added by the freezeframe library we use to play/pause animated images
  img,
  video,
  .ff-container {
    height: auto;
    object-fit: contain;
    display: block;
    margin: var(--content-rhythm) auto;
    max-width: 100%;
    max-height: calc(50vh + 180px);
    border-radius: var(--radius);
  }

  img.subscription-icon {
    max-height: 13px;
    max-width: 21px;
    display: inline-block;
    vertical-align: middle;
    margin: 0 0 0.05em;
    border-radius: 0;
  }

  img.community-leader-icon {
    height: 0.95em;
    max-height: 22px;
    display: inline-block;
    vertical-align: middle;
    margin: 0 0 0.05em;
    border-radius: 0;
    aspect-ratio: 1 / 1;
  }

  .article-body-image-wrapper {
    cursor: zoom-in;
  }

  iframe {
    width: 100%;
    border: 0;
    margin: 0 0 var(--content-rhythm) 0;
    border-radius: var(--radius);
  }

  .fluidvids {
    margin: 0 0 var(--content-rhythm) 0;

    iframe {
      margin: 0;
    }
  }

  .table-wrapper-paragraph {
    width: 100%;
    overflow-x: auto;
    margin: 0 0 var(--content-rhythm) 0;

    table {
      margin: 0;
    }
  }

  table {
    margin: 0 0 var(--content-rhythm) 0;
    border-collapse: collapse;
    border-spacing: 0;

    th,
    td {
      padding: var(--su-2);
      border: 1px solid var(--base-20);
    }

