            "description": "unprocessable"
          }
        },
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "badge_achievement": {
                    "type": "object",
                    "properties": {
                      "user_id": {
                        "type": "integer"
                      },
                      "badge_id": {
                        "type": "integer"
                      },
                      "rewarding_context_message_markdown": {
                        "type": "string"
                      },
                      "include_default_description": {
