            "schema": {
              "type": "string"
            },
            "example": "321"
          },
          {
            "name": "p_id",
            "in": "query",
            "required": false,
            "description": "Podcast Episode identifier. Provide this to fetch comments belonging to a specific podcast episode.",
            "schema": {
              "type": "string"
            },
            "example": "321"
          },
          {
            "name": "page",
            "in": "query",
            "required": false,
            "description": "Pagination page index for top-level comments.",
            "schema": {
              "type": "string"
            },
            "example": "321"
          }
        ],
        "responses": {
          "200": {
            "description": "A List of Comments",
